package com.example.csvbatchlauncher;

import java.io.IOException; import java.nio.file.Files; import java.nio.file.Path; import java.security.DigestInputStream; import java.security.MessageDigest; import java.util.HexFormat;
import jakarta.annotation.PostConstruct; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;

@Component
public class BatchLaunchQueue {
    private final JdbcTemplate jdbc; private final BatchProcessExecutor executor;
    public BatchLaunchQueue(JdbcTemplate jdbc, BatchProcessExecutor executor) { this.jdbc=jdbc; this.executor=executor; }
    @PostConstruct public void recoverInterruptedJobs() { jdbc.update("UPDATE batch_launch_request SET status='QUEUED',started_at=NULL,error='Recovered after launcher restart' WHERE status='RUNNING'"); }
    public Result enqueue(Path file) { try { Path p=file.toAbsolutePath().normalize(); if(!Files.isRegularFile(p)) throw new IllegalArgumentException("CSV file does not exist"); BatchType type=BatchType.from(p); if(type==null) throw new IllegalArgumentException("Unsupported CSV filename"); String checksum=checksum(p), id="csv-sha256-"+checksum; jdbc.update("INSERT INTO batch_launch_request(request_id,file_path,checksum,batch_type,status) VALUES(?,?,?,?,'QUEUED') ON CONFLICT(request_id) DO UPDATE SET file_path=EXCLUDED.file_path,batch_type=EXCLUDED.batch_type,status=CASE WHEN batch_launch_request.status='FAILED' THEN 'QUEUED' ELSE batch_launch_request.status END,error=CASE WHEN batch_launch_request.status='FAILED' THEN NULL ELSE batch_launch_request.error END,finished_at=CASE WHEN batch_launch_request.status='FAILED' THEN NULL ELSE batch_launch_request.finished_at END",id,p.toString(),checksum,type.key()); return status(id); } catch(IOException e){throw new IllegalArgumentException("Cannot read CSV",e);} }
    @Scheduled(fixedDelayString="${app.launcher.poll-interval}") public void processNext(){ jdbc.query("SELECT request_id,file_path,batch_type FROM batch_launch_request WHERE status='QUEUED' ORDER BY CASE batch_type WHEN 'results' THEN 10 WHEN 'fixtures' THEN 20 WHEN 'match-summary' THEN 30 WHEN 'team-stats' THEN 40 WHEN 'stats-player' THEN 50 WHEN 'point-by-point' THEN 60 ELSE 100 END, created_at LIMIT 1",rs->{String id=rs.getString(1),file=rs.getString(2),kind=rs.getString(3); jdbc.update("UPDATE batch_launch_request SET status='RUNNING',started_at=CURRENT_TIMESTAMP,attempts=attempts+1 WHERE request_id=? AND status='QUEUED'",id); try{boolean ok=executor.execute(BatchType.valueOf(kind.replace('-','_').toUpperCase()),Path.of(file)); jdbc.update("UPDATE batch_launch_request SET status=?,finished_at=CURRENT_TIMESTAMP,exit_code=? WHERE request_id=?",ok?"COMPLETED":"FAILED",ok?0:1,id);}catch(Exception e){jdbc.update("UPDATE batch_launch_request SET status='FAILED',finished_at=CURRENT_TIMESTAMP,error=? WHERE request_id=?",e.toString(),id);}}); }
    public Result status(String id){ return jdbc.queryForObject("SELECT request_id,status,batch_type FROM batch_launch_request WHERE request_id=?",(rs,n)->new Result(rs.getString(1),rs.getString(2),BatchType.valueOf(rs.getString(3).replace('-','_').toUpperCase())),id); }
    private String checksum(Path p)throws IOException{try{var d=MessageDigest.getInstance("SHA-256");try(var in=new DigestInputStream(Files.newInputStream(p),d)){in.transferTo(java.io.OutputStream.nullOutputStream());}return HexFormat.of().formatHex(d.digest());}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    public record Result(String requestId,String status,BatchType type){}
}
